<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\LearningOffer;
use App\Models\Teacher;
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class LearningOfferController extends Controller {
 private function scope(string $scope): string {abort_unless(in_array($scope,['dshi','additional'],true),404);return $scope;}
 public function index(string $scope){$scope=$this->scope($scope);return view('admin.learning.index',['scope'=>$scope,'items'=>LearningOffer::scope($scope)->orderBy('sort')->orderBy('title')->paginate(30)]);}
 public function edit(string $scope,string $id='new'){$scope=$this->scope($scope);$record=$id==='new'?null:LearningOffer::scope($scope)->findOrFail($id);$teachers=Teacher::where('is_active',true)->orderBy('sort')->orderBy('name')->get(['id','name','position']);return view('admin.learning.edit',compact('scope','record','teachers'));}
 public function save(Request $r,string $scope,string $id='new'){$scope=$this->scope($scope);$record=$id==='new'?new LearningOffer:LearningOffer::scope($scope)->findOrFail($id);$d=$r->validate(['title'=>'required|string|max:255','slug'=>'nullable|string|max:255','kind'=>'nullable|string|max:255','age'=>'nullable|string|max:255','hours'=>'nullable|string|max:100','format'=>'nullable|string|max:255','audience'=>'nullable|string|max:255','symbol'=>'nullable|string|max:20','description'=>'nullable|string','sort'=>'nullable|integer|min:0','is_active'=>'nullable|boolean','admission'=>'nullable|string','curriculum'=>'nullable|string','outcomes'=>'nullable|string','requirements'=>'nullable|string','assessment'=>'nullable|string','certificate'=>'nullable|string','teacher_ids'=>'nullable|array','teacher_ids.*'=>'integer|exists:teachers,id','event_slugs'=>'nullable|string']);$slug=Str::slug($d['slug']?:$d['title']);$exists=LearningOffer::where('scope',$scope)->where('slug',$slug)->when($record->exists,fn($q)=>$q->whereKeyNot($record->id))->exists();if($exists)return back()->withErrors(['slug'=>'Такой slug уже используется в этом разделе.'])->withInput();$content=$record->content??[];foreach(['admission','curriculum','outcomes','requirements','assessment','certificate'] as $key){$value=trim((string)($d[$key]??''));if($value!=='')$content[$key]=$value;else unset($content[$key]);unset($d[$key]);}$content['teacher_ids']=array_values(array_unique(array_map('intval',$d['teacher_ids']??[])));unset($d['teacher_ids']);$content['event_slugs']=array_values(array_filter(array_unique(array_map('trim',preg_split('/\r\n|\r|\n/',(string)($d['event_slugs']??''))))));unset($d['event_slugs']);$d['scope']=$scope;$d['slug']=$slug;$d['is_active']=$r->boolean('is_active');$d['content']=$content;$record->fill($d)->save();return redirect()->route('admin.learning.index',$scope)->with('success','Программа сохранена');}
 public function destroy(string $scope,LearningOffer $offer){$scope=$this->scope($scope);abort_unless($offer->scope===$scope,404);$offer->delete();return back()->with('success','Программа удалена');}
}